#include <iostream>
#include <vector>
#include <string>
using namespace std;

string solveCase(int n, int m, const vector<int>& p) {
    // bucket[v] 存储所有能力值为 v 的人员的原下标（从小到大）
    vector<vector<int>> bucket(n + 1);
    for (int i = 0; i < n; i++) {
        bucket[p[i]].push_back(i);
    }

    vector<bool> removed(n, false);

    // 按能力值从小到大淘汰
    for (int v = 1; v <= n && m > 0; v++) {
        int sz = (int)bucket[v].size();
        if (sz <= m) {
            for (int idx : bucket[v]) {
                removed[idx] = true;
            }
            m -= sz;
        } else {
            for (int i = 0; i < m; i++) {
                removed[bucket[v][i]] = true;
            }
            m = 0;
            break;
        }
    }

    string ans;
    bool first = true;
    for (int i = 0; i < n; i++) {
        if (!removed[i]) {
            if (!first) ans += " ";
            ans += to_string(p[i]);
            first = false;
        }
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
