    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;
        vector<int> p(n);
        for (int i = 0; i < n; i++) {
            cin >> p[i];
        }
        cout << solveCase(n, m, p) << '\n';
    }
    return 0;
}
